export interface ExperienceClock { now(): string; }
export class LocalMonotonicExperienceClock implements ExperienceClock { private current: string; constructor(initial: string) { this.current = iso(initial, "EXPERIENCE_CLOCK_INVALID"); } now(): string { return this.current; } advanceTo(nextInput: unknown): void { const next = iso(nextInput, "EXPERIENCE_CLOCK_INVALID"); if (Date.parse(next) < Date.parse(this.current)) fail("EXPERIENCE_CLOCK_ROLLBACK"); this.current = next; } }

